def compute(vars):
    old = vars["v2"]
    if old == 0:
        return None

    value = vars["v1"] / old
    return {
        "value": value,
        "trace": {
            "numerator_2003": vars["v1"],
            "denominator_2002": old,
            "ratio": value,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
